package example.clean.outer;

import example.clean.application.PlaceOrder;
import java.util.function.Consumer;
import org.springframework.transaction.support.TransactionTemplate;

public final class ReceiptEntry {
    private final TransactionalOrders orders;
    private final TransactionTemplate callerTransaction;
    private final Consumer<PlaceOrder.Result> committedReceipt;

    public ReceiptEntry(TransactionalOrders orders, TransactionTemplate callerTransaction,
            Consumer<PlaceOrder.Result> committedReceipt) {
        this.orders = orders;
        this.callerTransaction = callerTransaction;
        this.committedReceipt = committedReceipt;
    }

    public void submit(PlaceOrder.Actor actor, PlaceOrder.Command command) {
        callerTransaction.executeWithoutResult(status -> {
            var result = orders.submit(actor, command);
            committedReceipt.accept(result);
        });
    }
}
